create table if not exists public.platform_owner_contract_acknowledgments(
 id uuid primary key default gen_random_uuid(),owner_record_id uuid not null unique references public.platform_owner_records(id) on delete cascade,profile_id uuid not null references public.profiles(id),signed_name text not null,terms_version text not null default '2026-08-25',signed_at timestamptz not null default now());
alter table public.platform_owner_contract_acknowledgments enable row level security;
create policy "Owners view own contract" on public.platform_owner_contract_acknowledgments for select to authenticated using(profile_id=(select auth.uid()));
create or replace function public.sign_platform_owner_contract(p_token uuid,p_signed_name text) returns void language plpgsql security definer set search_path='' as $$ declare v_invite public.platform_owner_invitations%rowtype;begin select * into v_invite from public.platform_owner_invitations where token=p_token for update;if v_invite.id is null or v_invite.expires_at<now() then raise exception 'Invitation is unavailable.';end if;if lower(coalesce(auth.jwt()->>'email',''))<>lower(v_invite.email) then raise exception 'Use the invited email address.';end if;if char_length(trim(p_signed_name))<2 then raise exception 'Type your full name.';end if;insert into public.platform_owner_contract_acknowledgments(owner_record_id,profile_id,signed_name) values(v_invite.owner_record_id,(select auth.uid()),trim(p_signed_name)) on conflict(owner_record_id) do update set profile_id=excluded.profile_id,signed_name=excluded.signed_name,signed_at=now();update public.platform_owner_records set profile_id=(select auth.uid()),updated_at=now() where id=v_invite.owner_record_id;end;$$;
revoke all on function public.sign_platform_owner_contract(uuid,text) from public;grant execute on function public.sign_platform_owner_contract(uuid,text) to authenticated;
